window.REPLIKEN = [{"nr": 1, "speaker": "PF", "phase": "Einstieg", "a": 10.0, "b": 13.52, "lines": [{"a": 10.0, "b": 11.52, "text": "Guten Morgen, Sami."}, {"a": 11.52, "b": 13.67, "text": "Darf ich mich kurz zu Ihnen setzen?"}]}, {"nr": 2, "speaker": "P", "phase": "Einstieg", "a": 13.92, "b": 18.48, "lines": [{"a": 14.36, "b": 16.38, "text": "Ja, setzen Sie sich."}, {"a": 16.38, "b": 18.63, "text": "Sie sind doch die aus der Nachbarschaft, oder?"}]}, {"nr": 3, "speaker": "PF", "phase": "Einstieg", "a": 18.88, "b": 25.6, "lines": [{"a": 19.14, "b": 23.6, "text": "Genau. Ich bin Takiyat, Pflegefachfrau in Ausbildung."}, {"a": 23.6, "b": 25.75, "text": "Wie geht es Ihnen heute mit der Luft?"}]}, {"nr": 4, "speaker": "P", "phase": "Einstieg", "a": 26.0, "b": 31.04, "lines": [{"a": 26.82, "b": 31.19, "text": "Geht so. Ohne den Sauerstoff zwischendurch komme ich nicht weit."}]}, {"nr": 5, "speaker": "PF", "phase": "Einstieg", "a": 31.44, "b": 41.04, "lines": [{"a": 31.52, "b": 35.88, "text": "Bei der Morgenpflege habe ich die Zigaretten in Ihrem Nachtschrank gesehen."}, {"a": 35.88, "b": 38.3, "text": "Ich möchte Ihnen keine Vorwürfe machen."}, {"a": 38.3, "b": 41.19, "text": "Dürfte ich trotzdem kurz mit Ihnen darüber sprechen?"}]}, {"nr": 6, "speaker": "P", "phase": "Einstieg", "a": 41.44, "b": 46.64, "lines": [{"a": 41.68, "b": 43.38, "text": "Wenn's sein muss."}, {"a": 43.38, "b": 46.79, "text": "Mein Arzt erzählt mir schon seit Jahren, dass ich damit aufhören soll."}]}, {"nr": 7, "speaker": "PF", "phase": "Ask", "a": 47.44, "b": 51.44, "lines": [{"a": 47.44, "b": 49.28, "text": "Dann frage ich einfach mal:"}, {"a": 49.28, "b": 51.59, "text": "Wie viel rauchen Sie zurzeit am Tag?"}]}, {"nr": 8, "speaker": "P", "phase": "Ask", "a": 51.84, "b": 55.28, "lines": [{"a": 51.82, "b": 55.43, "text": "Eine Schachtel. Beim Skat am Wochenende auch mehr."}]}, {"nr": 9, "speaker": "PF", "phase": "Ask", "a": 55.68, "b": 57.52, "lines": [{"a": 55.68, "b": 57.67, "text": "Und seit wann rauchen Sie?"}]}, {"nr": 10, "speaker": "P", "phase": "Ask", "a": 57.92, "b": 61.04, "lines": [{"a": 58.9, "b": 61.19, "text": "Seit über vierzig Jahren."}]}, {"nr": 11, "speaker": "PF", "phase": "Advise", "a": 61.84, "b": 77.36, "lines": [{"a": 61.96, "b": 63.82, "text": "Danke für Ihre Offenheit."}, {"a": 63.82, "b": 66.18, "text": "Ich sage Ihnen ehrlich, was ich denke:"}, {"a": 66.18, "b": 71.46, "text": "Mit dem Rauchen aufzuhören ist das Wichtigste, was Sie bei COPD für Ihre Lunge tun können."}, {"a": 71.46, "b": 74.2, "text": "Der Schaden, der schon da ist, geht nicht mehr weg."}, {"a": 74.2, "b": 77.51, "text": "Aber ohne Rauch schreitet die Krankheit langsamer voran."}]}, {"nr": 12, "speaker": "P", "phase": "Advise", "a": 77.76, "b": 85.36, "lines": [{"a": 77.8, "b": 82.36, "text": "Ach was. Von meinen Skatbrüdern rauchen auch alle, und krank ist keiner."}, {"a": 82.36, "b": 85.51, "text": "Der Martin ist letztes Jahr sogar einen Halbmarathon gelaufen."}]}, {"nr": 13, "speaker": "PF", "phase": "Advise", "a": 85.76, "b": 94.72, "lines": [{"a": 85.82, "b": 89.06, "text": "Sie sehen bei Ihren Freunden, dass es auch anders gehen kann."}, {"a": 89.06, "b": 91.0, "text": "Jede Lunge reagiert anders."}, {"a": 91.0, "b": 94.87, "text": "Ihre Lunge ist schon krank, und das merken Sie jeden Tag beim Atmen."}]}, {"nr": 14, "speaker": "P", "phase": "Advise", "a": 95.12, "b": 98.72, "lines": [{"a": 95.24, "b": 98.87, "text": "Ja … die Treppe zu meiner Wohnung schaffe ich kaum noch."}]}, {"nr": 15, "speaker": "PF", "phase": "Advise", "a": 99.12, "b": 106.8, "lines": [{"a": 99.24, "b": 102.7, "text": "Noch etwas ist mir wichtig, weil Sie Sauerstoff bekommen:"}, {"a": 102.7, "b": 106.95, "text": "In der Nähe von Sauerstoff zu rauchen ist gefährlich, es kann schnell brennen."}]}, {"nr": 16, "speaker": "P", "phase": "Advise", "a": 107.2, "b": 109.36, "lines": [{"a": 107.24, "b": 109.51, "text": "Daran habe ich gar nicht gedacht."}]}, {"nr": 17, "speaker": "PF", "phase": "Assess", "a": 110.16, "b": 115.44, "lines": [{"a": 110.16, "b": 112.84, "text": "Darf ich Ihnen zwei kurze Fragen stellen?"}, {"a": 112.84, "b": 115.59, "text": "Wann rauchen Sie morgens die erste Zigarette?"}]}, {"nr": 18, "speaker": "P", "phase": "Assess", "a": 115.84, "b": 119.28, "lines": [{"a": 115.84, "b": 117.66, "text": "Direkt nach dem Aufstehen."}, {"a": 117.66, "b": 119.43, "text": "Sonst komme ich nicht in Gang."}]}, {"nr": 19, "speaker": "PF", "phase": "Assess", "a": 119.68, "b": 125.84, "lines": [{"a": 119.66, "b": 123.92, "text": "Und fällt es Ihnen schwer, dort nicht zu rauchen, wo es verboten ist?"}, {"a": 123.92, "b": 125.99, "text": "Hier im Krankenhaus zum Beispiel?"}]}, {"nr": 20, "speaker": "P", "phase": "Assess", "a": 126.24, "b": 131.36, "lines": [{"a": 126.4, "b": 129.04, "text": "Ehrlich gesagt, ja."}, {"a": 129.04, "b": 131.51, "text": "Deshalb liegt die Schachtel ja im Nachtschrank."}]}, {"nr": 21, "speaker": "PF", "phase": "Assess", "a": 131.76, "b": 145.28, "lines": [{"a": 131.8, "b": 135.26, "text": "Das spricht für eine deutliche körperliche Abhängigkeit."}, {"a": 135.26, "b": 140.14, "text": "Das ist keine Willensschwäche, sondern eine Abhängigkeit, die man gut behandeln kann."}, {"a": 140.14, "b": 142.44, "text": "Auf einer Skala von null bis zehn:"}, {"a": 142.44, "b": 145.43, "text": "Wie wichtig ist es Ihnen gerade, etwas zu verändern?"}]}, {"nr": 22, "speaker": "P", "phase": "Assess", "a": 145.68, "b": 151.04, "lines": [{"a": 145.88, "b": 148.1, "text": "Vielleicht eine Vier."}, {"a": 148.1, "b": 149.46, "text": "Wegen meiner Frau."}, {"a": 149.46, "b": 151.19, "text": "Die macht sich große Sorgen."}]}, {"nr": 23, "speaker": "PF", "phase": "Assess", "a": 151.44, "b": 154.16, "lines": [{"a": 151.44, "b": 154.31, "text": "Eine Vier. Und warum keine Zwei?"}]}, {"nr": 24, "speaker": "P", "phase": "Assess", "a": 154.56, "b": 158.24, "lines": [{"a": 154.56, "b": 157.42, "text": "Weil ich wieder ohne Pause zur Kneipe laufen will."}, {"a": 157.42, "b": 158.39, "text": "Zum Skat."}]}, {"nr": 25, "speaker": "PF", "phase": "Assist", "a": 159.04, "b": 173.84, "lines": [{"a": 159.1, "b": 160.74, "text": "Das sind gute Gründe."}, {"a": 160.74, "b": 162.86, "text": "Sie müssen heute nichts entscheiden."}, {"a": 162.86, "b": 167.5, "text": "Wenn Sie möchten, spreche ich mit der Ärztin über eine Nikotinersatztherapie."}, {"a": 167.5, "b": 171.94, "text": "Dabei bekommt Ihr Körper Nikotin, aber ohne die Schadstoffe aus dem Rauch."}, {"a": 171.94, "b": 173.99, "text": "Das lindert die Entzugserscheinungen."}]}, {"nr": 26, "speaker": "P", "phase": "Assist", "a": 174.24, "b": 176.24, "lines": [{"a": 174.3, "b": 176.39, "text": "Und wie funktioniert das?"}]}, {"nr": 27, "speaker": "PF", "phase": "Assist", "a": 176.64, "b": 192.32, "lines": [{"a": 176.62, "b": 179.38, "text": "Zum Beispiel mit einem Nikotinpflaster:"}, {"a": 179.38, "b": 184.52, "text": "Das kleben Sie morgens auf eine unbehaarte Hautstelle, jeden Tag an eine andere."}, {"a": 184.52, "b": 187.7, "text": "Es gibt das Nikotin gleichmäßig über den Tag ab."}, {"a": 187.7, "b": 192.47, "text": "Die Stärke legt die Ärztin fest, und nach einigen Wochen wird sie langsam verringert."}]}, {"nr": 28, "speaker": "P", "phase": "Assist", "a": 192.72, "b": 195.04, "lines": [{"a": 192.86, "b": 195.19, "text": "Hat das Pflaster Nebenwirkungen?"}]}, {"nr": 29, "speaker": "PF", "phase": "Assist", "a": 195.44, "b": 210.16, "lines": [{"a": 195.44, "b": 198.94, "text": "Manchmal wird die Haut unter dem Pflaster rot oder juckt."}, {"a": 198.94, "b": 202.2, "text": "Deshalb kleben Sie es jeden Tag an eine andere Stelle."}, {"a": 202.2, "b": 205.92, "text": "Und wenn Sie nachts unruhig schlafen oder sehr lebhaft träumen,"}, {"a": 205.92, "b": 208.34, "text": "können Sie es vor dem Schlafengehen abnehmen."}, {"a": 208.34, "b": 210.31, "text": "Das besprechen wir mit der Ärztin."}]}, {"nr": 30, "speaker": "P", "phase": "Assist", "a": 210.56, "b": 213.36, "lines": [{"a": 210.6, "b": 213.51, "text": "Und beim Skat? Da raucht doch jeder."}]}, {"nr": 31, "speaker": "PF", "phase": "Assist", "a": 213.76, "b": 234.4, "lines": [{"a": 213.72, "b": 216.72, "text": "Genau das ist eine schwierige Situation."}, {"a": 216.72, "b": 219.06, "text": "Dafür gibt es Nikotinkaugummis."}, {"a": 219.06, "b": 221.04, "text": "Wichtig ist die Kautechnik:"}, {"a": 221.04, "b": 224.04, "text": "langsam kauen, bis es leicht scharf schmeckt,"}, {"a": 224.04, "b": 227.3, "text": "dann in die Wangentasche legen, und später wieder kauen."}, {"a": 227.3, "b": 232.14, "text": "Und kurz vorher keinen Kaffee und keine Cola, sonst wirkt das Nikotin schlechter."}, {"a": 232.14, "b": 234.55, "text": "Vielleicht kann Ihre Frau Sie auch unterstützen."}]}, {"nr": 32, "speaker": "P", "phase": "Assist", "a": 234.8, "b": 238.08, "lines": [{"a": 234.94, "b": 236.58, "text": "Die würde sich freuen."}, {"a": 236.58, "b": 238.23, "text": "Die sagt das schon lange."}]}, {"nr": 33, "speaker": "PF", "phase": "Assist", "a": 238.48, "b": 249.52, "lines": [{"a": 238.48, "b": 242.42, "text": "Dazu gibt es eine kostenlose Telefonberatung zum Rauchstopp."}, {"a": 242.42, "b": 246.98, "text": "Dort ruft man Sie auf Wunsch zurück und begleitet Sie auch nach der Entlassung."}, {"a": 246.98, "b": 249.67, "text": "Ich gebe Ihnen ein Infoblatt mit allen Nummern."}]}, {"nr": 34, "speaker": "P", "phase": "Assist", "a": 249.92, "b": 254.0, "lines": [{"a": 250.02, "b": 254.15, "text": "Auf einen Schlag aufhören … das schaffe ich nicht."}]}, {"nr": 35, "speaker": "PF", "phase": "Assist", "a": 254.4, "b": 260.32, "lines": [{"a": 254.42, "b": 256.64, "text": "Dann gehen wir es Schritt für Schritt an."}, {"a": 256.64, "b": 260.47, "text": "Wären Sie bereit, das Pflaster hier im Krankenhaus auszuprobieren?"}]}, {"nr": 36, "speaker": "P", "phase": "Assist", "a": 260.72, "b": 263.12, "lines": [{"a": 260.92, "b": 263.27, "text": "Ausprobieren kann ich es ja mal."}]}, {"nr": 37, "speaker": "P", "phase": "Assist", "a": 263.52, "b": 266.24, "lines": [{"a": 263.66, "b": 266.39, "text": "Und wenn ich doch wieder eine rauche?"}]}, {"nr": 38, "speaker": "PF", "phase": "Assist", "a": 266.64, "b": 280.08, "lines": [{"a": 266.66, "b": 268.58, "text": "Dann ist das kein Scheitern."}, {"a": 268.58, "b": 271.54, "text": "Viele brauchen mehrere Versuche, bis es klappt."}, {"a": 271.54, "b": 274.7, "text": "Wichtig ist, dass Sie nicht aufgeben und darüber sprechen:"}, {"a": 274.7, "b": 278.24, "text": "mit mir, mit der Ärztin oder mit der Telefonberatung."}, {"a": 278.24, "b": 280.23, "text": "Die hilft auch nach einem Rückfall."}]}, {"nr": 39, "speaker": "PF", "phase": "Arrange", "a": 280.88, "b": 297.6, "lines": [{"a": 280.88, "b": 282.36, "text": "Dann halten wir fest:"}, {"a": 282.36, "b": 285.3, "text": "Ich spreche heute mit der Ärztin über das Pflaster."}, {"a": 285.3, "b": 287.1, "text": "Sie bekommen das Infoblatt."}, {"a": 287.1, "b": 291.62, "text": "Und morgen früh setze ich mich wieder zu Ihnen, und wir schauen, wie es Ihnen damit geht."}, {"a": 291.62, "b": 296.66, "text": "Unser Gespräch halte ich in der Pflegedokumentation fest, damit das ganze Team Bescheid weiß."}, {"a": 296.66, "b": 297.75, "text": "Passt das für Sie?"}]}, {"nr": 40, "speaker": "P", "phase": "Arrange", "a": 298.0, "b": 302.56, "lines": [{"a": 298.0, "b": 302.71, "text": "Ja. Und die Zigaretten … die kann meine Frau nachher mitnehmen."}]}, {"nr": 41, "speaker": "PF", "phase": "Arrange", "a": 302.96, "b": 308.48, "lines": [{"a": 303.0, "b": 305.04, "text": "Das ist ein guter erster Schritt."}, {"a": 305.04, "b": 307.36, "text": "Sie entscheiden, ich begleite Sie."}, {"a": 307.36, "b": 308.63, "text": "Bis morgen, Sami."}]}];
